from collections import Counter
from typing import Counter as CounterType, Tuple
Transcript = Tuple[int, bool, int]

def real(r: int, c: bool, w: int, y: int, k: int, n: int) -> Transcript:
    return ((k*r) % n, c, (r + (w if c else 0)) % n)

def simulated(z: int, c: bool, w: int, y: int, k: int, n: int) -> Transcript:
    return (((k*z) - (y if c else 0)) % n, c, z)

def distribution(kind: str, c: bool, w: int, k: int, n: int) -> CounterType[Transcript]:
    y = (k*w) % n
    f = real if kind == "real" else simulated
    return Counter(f(x, c, w, y, k, n) for x in range(n))

def main() -> None:
    n, k, w = 12, 4, 5
    for c in (False, True):
        lhs, rhs = distribution("real", c, w, k, n), distribution("sim", c, w, k, n)
        assert lhs == rhs
        print(f"challenge {int(c)}: exact equality across {sum(lhs.values())} tapes")

if __name__ == "__main__":
    main()

from typing import List

def accepted(commitment: int, challenge: int, target: int, n: int) -> List[int]:
    return [z for z in range(n) if (2*z) % n == (commitment + challenge*target) % n]

def main() -> None:
    n, target = 8, 1
    assert all((2*w) % n != target for w in range(n))
    for a in range(n):
        zero, one = accepted(a, 0, target, n), accepted(a, 1, target, n)
        assert not (zero and one)
        print(a, {0: zero, 1: one})

if __name__ == "__main__":
    main()

